def test_filler_words_before_review_token_stripped():
    kind, desc, rounds = _parse_webgpt_review_query(
        ["for", "a", "/review-code", "of", "your", "recent", "code", "changes", "over", "2", "iteration", "rounds"]
    )
    assert kind == "code"
    assert "your recent code changes" in desc
    # The leading "of" should be stripped iteratively.
    assert not desc.lower().startswith("of ")
    assert rounds == 2


